        return isFunctionKeyToken(parsed.key);
    }
    return (isFunctionKeyToken(parsed.key) ||
        [
            'Backspace',
            'Delete',
            'Enter',
            'Escape',
            'Tab',
            'ArrowLeft',
            'ArrowRight',
            'ArrowUp',
            'ArrowDown',
            'PageUp',
            'PageDown'
